package com.pardal.kitapligim;
import org.junit.Test;
import org.json.*;
import static org.junit.Assert.*;
public class SyncRulesTest {
 private JSONObject book(String title) throws Exception {return Book.normalize(new JSONObject().put("id","b1").put("profile","Güleser").put("title",title).put("status","reading").put("totalPages",200).put("currentPage",40).put("syncStatus","synced").put("remotePageId","r1").put("remoteEditedAt","2026-10-18T10:00:00Z"));}
 @Test public void rejectsProgressPastTotal() throws Exception {JSONObject b=book("Bir kitap");b.put("currentPage",201);assertThrows(IllegalArgumentException.class,()->Book.normalize(b));}
 @Test public void rejectsUnknownFamilyMember() throws Exception {JSONObject b=book("Bir kitap");b.put("profile","Misafir");assertThrows(IllegalArgumentException.class,()->Book.normalize(b));}
 @Test public void rejectsReversedDates() throws Exception {JSONObject b=book("Bir kitap");b.put("startedAt","2026-10-18").put("finishedAt","2026-10-17");assertThrows(IllegalArgumentException.class,()->Book.normalize(b));}
 @Test public void cleanLocalAcceptsNotionChange() throws Exception {JSONObject l=book("Eski"),r=book("Yeni");r.put("remoteEditedAt","2026-10-18T11:00:00Z");assertEquals("Yeni",SyncMerge.merge(l,r).getString("title"));}
 @Test public void unsentChangeSurvivesUnchangedRemote() throws Exception {JSONObject l=book("Telefondaki").put("syncStatus","pending"),r=book("Eski");JSONObject x=SyncMerge.merge(l,r);assertEquals("Telefondaki",x.getString("title"));assertEquals("pending",x.getString("syncStatus"));}
 @Test public void simultaneousEditsPreserveBothVersions() throws Exception {JSONObject l=book("Telefondaki").put("syncStatus","pending"),r=book("Notiondaki").put("remoteEditedAt","2026-10-18T11:00:00Z");JSONObject x=SyncMerge.merge(l,r);assertEquals("conflict",x.getString("syncStatus"));assertEquals("Telefondaki",x.getString("title"));assertEquals("Notiondaki",x.getJSONObject("conflictRemote").getString("title"));}
 @Test public void equalEditsDoNotCreateConflict() throws Exception {JSONObject l=book("Aynı").put("syncStatus","pending"),r=book("Aynı").put("remoteEditedAt","2026-10-18T11:00:00Z");assertEquals("synced",SyncMerge.merge(l,r).getString("syncStatus"));}
 @Test public void localChoiceAdvancesBaselineWithoutLosingLocalEdit() throws Exception {JSONObject l=book("Telefondaki").put("syncStatus","pending"),r=book("Notiondaki").put("remoteEditedAt","2026-10-18T11:00:00Z");JSONObject x=SyncMerge.resolve(SyncMerge.merge(l,r),false);assertEquals("Telefondaki",x.getString("title"));assertEquals("pending",x.getString("syncStatus"));assertEquals(r.getString("remoteEditedAt"),x.getString("remoteEditedAt"));assertFalse(x.has("conflictRemote"));}
 @Test public void remoteDeletionConflictsWithPendingLocalEdit() throws Exception {JSONObject l=book("Kitap").put("syncStatus","pending").put("notes","Yeni not"),r=book("Kitap").put("deleted",true).put("remoteEditedAt","2026-10-18T11:00:00Z");assertEquals("conflict",SyncMerge.merge(l,r).getString("syncStatus"));}
 @Test public void newNotionRecordGetsStableIdentity() throws Exception {JSONObject b=book("Türkçe kitap");JSONObject p=NotionCodec.toProperties(b);p.getJSONObject("Uygulama ID").put("rich_text",new JSONArray());JSONObject page=new JSONObject().put("id","remote-123").put("last_edited_time","2026-10-18T10:00:00Z").put("properties",p);assertEquals("notion-remote-123",NotionCodec.fromPage(page).getString("id"));}
 @Test public void longTurkishNotesRoundtripWithoutTruncation() throws Exception {JSONObject b=book("İçimizdeki Şeytan");String notes="Bir alıntı 🦋, güzel bir iz. ".repeat(200);b.put("notes",notes).put("profile","Lila");JSONObject p=NotionCodec.toProperties(b);JSONArray blocks=p.getJSONObject("Notlar").getJSONArray("rich_text");assertTrue(blocks.length()>1);for(int i=0;i<blocks.length();i++)assertTrue(blocks.getJSONObject(i).getJSONObject("text").getString("content").length()<=2000);JSONObject page=new JSONObject().put("id","r1").put("last_edited_time","2026-10-18T10:00:00Z").put("properties",p);JSONObject back=NotionCodec.fromPage(page);assertEquals(notes,back.getString("notes"));assertEquals("Lila",back.getString("profile"));assertEquals(b.getString("title"),back.getString("title"));}
 @Test public void nullDateAndCoverRemainEmpty() throws Exception {JSONObject b=book("Kitap");JSONObject p=NotionCodec.toProperties(b);JSONObject page=new JSONObject().put("id","r1").put("last_edited_time","2026-10-18T10:00:00Z").put("properties",p);JSONObject back=NotionCodec.fromPage(page);assertEquals("",back.getString("cover"));assertEquals("",back.getString("startedAt"));}
}
